public class Main {
    public static void main(String[] args) {
        List<String> palabras = Arrays.asList("Java", "Lamda", "Hi", "Programacion", "Web");

        Collections.sort(palabras, (a, b) -> a.length() - b.length());

        System.out.println(palabras);
    }
}

