@FunctionalInterface
interface OperacionNumerica {
    int operar(int a, int b);
}

public class Main {

    static int aplicarOperacion(int a, int b, OperacionNumerica op) {
        return op.operar(a, b);
    }

    public static void main(String[] args) {
        OperacionNumerica suma = (a, b) -> a + b;
        OperacionNumerica resta = (a, b) -> a - b;
        OperacionNumerica multiplicar = (a, b) -> a * b;

        System.out.println("Suma: " + aplicarOperacion(10, 3, suma));
        System.out.println("Resta: " + aplicarOperacion(10, 3, resta));
        System.out.println("Multiplicar: " + aplicarOperacion(10, 3, multiplicar));
    }
}
